public class MainActivity extends Activity{static final int P=7;TextView v;public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);v=new TextView(this);v.setText("DIAG E — manipolazione DEX/ZIP\n\nNessuna libreria apksig e nessun permesso di installazione. Selezionando un APK viene creata in cache una copia in cui, solo dentro classes.dex, la stringa diagnostica app-measurement.com viene sostituita con xxxxxxxxxxx.invalid se presente. NON viene installata.");Button x=new Button(this);x.setText("Seleziona APK per test DEX");x.setOnClickListener(q->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.android.package-archive");startActivityForResult(i,P);});l.addView(v);l.addView(x);setContentView(l);}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==P&&c==RESULT_OK&&d!=null)new Thread(()->run(d.getData())).start();}void run(Uri u){try{File in=new File(getCacheDir(),"in.apk"),out=new File(getCacheDir(),"dex-test.apk");try(InputStream s=getContentResolver().openInputStream(u);OutputStream o=new FileOutputStream(in)){byte[]b=new byte[65536];int n;while((n=s.read(b))>0)o.write(b,0,n);}int hits=0;try(ZipFile z=new ZipFile(in);ZipOutputStream zo=new ZipOutputStream(new FileOutputStream(out))){Enumeration<? extends ZipEntry> en=z.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();byte[] b=read(z.getInputStream(e));if("classes.dex".equals(e.getName()))hits+=replace(b,"app-measurement.com","xxxxxxxxxxx.invalid");ZipEntry ne=new ZipEntry(e.getName());zo.putNextEntry(ne);if(!e.isDirectory())zo.write(b);zo.closeEntry();}}final int h=hits;runOnUiThread(()->v.append("\n\nTest completato. Occorrenze modificate: "+h));}catch(Exception e){runOnUiThread(()->v.append("\nERRORE: "+e));}}static byte[] read(InputStream s)throws Exception{try(InputStream x=s;ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[65536];int n;while((n=x.read(b))>0)o.write(b,0,n);return o.toByteArray();}}static int replace(byte[]b,String a,String r)throws Exception{byte[]x=a.getBytes("UTF-8"),y=r.getBytes("UTF-8");if(x.length!=y.length)return 0;int h=0;outer:for(int i=0;i<=b.length-x.length;i++){for(int j=0;j<x.length;j++)if(b[i+j]!=x[j])continue outer;System.arraycopy(y,0,b,i,y.length);h++;i+=x.length-1;}return h;}}
